import { oneBlankEquation, productEquation, type CalculationDefinition, type InputDefinition } from "@/lib/engine";

const n = (key: string, label: string, symbol: string, unit = "", unitGroup: InputDefinition["unitGroup"] = "dimensionless", placeholder = "e.g. 2"): InputDefinition => ({ key, label, symbol, unit, unitGroup, placeholder });
const maths: CalculationDefinition[] = [];
const custom = (cfg: Omit<Parameters<typeof oneBlankEquation>[0], "domain">) => oneBlankEquation({...cfg, domain:"maths"});
const prod = (cfg: Omit<Parameters<typeof productEquation>[0], "domain">) => productEquation({...cfg, domain:"maths"});

// Algebra & functions
maths.push(custom({id:"quadratic-formula",category:"Algebra",title:"Quadratic roots",description:"Solve ax² + bx + c = 0",equation:"x = (−b ± √(b²−4ac)) / 2a",aliases:["quadratic","quadratic formula","roots","solve quadratic"],inputs:[n("x1","Root 1","x₁"),n("x2","Root 2","x₂"),n("a","Coefficient a","a"),n("b","Coefficient b","b"),n("c","Coefficient c","c")],derive:(target,v)=>{const d=v.b*v.b-4*v.a*v.c;if(target==="x1")return {value:(-v.b+Math.sqrt(d))/(2*v.a),rearranged:"x₁ = (−b + √(b²−4ac))/2a"};if(target==="x2")return {value:(-v.b-Math.sqrt(d))/(2*v.a),rearranged:"x₂ = (−b − √(b²−4ac))/2a"};if(target==="c")return {value:-v.a*(v.x1*v.x2),rearranged:"c = ax₁x₂"};if(target==="b")return {value:-v.a*(v.x1+v.x2),rearranged:"b = −a(x₁+x₂)"};return {value:-v.b/(v.x1+v.x2),rearranged:"a = −b/(x₁+x₂)"};}}));
maths.push(custom({id:"discriminant",category:"Algebra",title:"Quadratic discriminant",description:"Determine the discriminant of a quadratic",equation:"Δ = b² − 4ac",aliases:["discriminant","delta quadratic"],inputs:[n("D","Discriminant","Δ"),n("a","Coefficient a","a"),n("b","Coefficient b","b"),n("c","Coefficient c","c")],derive:(target,v)=>({value:target==="D"?v.b*v.b-4*v.a*v.c:target==="c"?(v.b*v.b-v.D)/(4*v.a):target==="a"?(v.b*v.b-v.D)/(4*v.c):Math.sqrt(v.D+4*v.a*v.c),rearranged:"Δ = b² − 4ac"})}));
maths.push(custom({id:"factor-theorem-value",category:"Algebra",title:"Polynomial value",description:"Evaluate a polynomial using coefficients at x",equation:"f(x) = ax³ + bx² + cx + d",aliases:["polynomial value","function value"],inputs:[n("y","f(x)","f(x)"),n("a","x³ coefficient","a"),n("b","x² coefficient","b"),n("c","x coefficient","c"),n("d","Constant","d"),n("x","Input","x")],derive:(target,v)=>({value:target==="y"?v.a*v.x**3+v.b*v.x**2+v.c*v.x+v.d:v.d-v.a*v.x**3-v.b*v.x**2-v.c*v.x,rearranged:"f(x) = ax³ + bx² + cx + d"})}));
maths.push(custom({id:"binomial-term",category:"Algebra",title:"Binomial term",description:"Coefficient and term in a binomial expansion",equation:"Tᵣ₊₁ = C(n,r)aⁿ⁻ʳbʳ",aliases:["binomial expansion","binomial term","nCr"],inputs:[n("T","Term","T"),n("n","Power","n"),n("r","Term index","r"),n("a","First term","a"),n("b","Second term","b")],derive:(target,v)=>{const choose=(N:number,R:number)=>{let q=1;for(let i=1;i<=R;i++)q*=((N-i+1)/i);return q};return {value:choose(v.n,v.r)*v.a**(v.n-v.r)*v.b**v.r,rearranged:"Tᵣ₊₁ = C(n,r)aⁿ⁻ʳbʳ"};}}));
maths.push(custom({id:"combination",category:"Discrete",title:"Combinations",description:"Number of unordered selections",equation:"nCr = n!/[r!(n−r)!]",aliases:["ncr","combinations"],inputs:[n("C","Combinations","nCr"),n("n","Population","n"),n("r","Selected","r")],derive:(target,v)=>{const fact=(x:number)=>{let p=1;for(let i=2;i<=x;i++)p*=i;return p};return {value:target==="C"?fact(v.n)/(fact(v.r)*fact(v.n-v.r)):target==="r"?v.r:v.n,rearranged:"nCr = n!/[r!(n−r)!]"};}}));
maths.push(custom({id:"permutation",category:"Discrete",title:"Permutations",description:"Number of ordered selections",equation:"nPr = n!/(n−r)!",aliases:["npr","permutations"],inputs:[n("P","Permutations","nPr"),n("n","Population","n"),n("r","Selected","r")],derive:(target,v)=>{const fact=(x:number)=>{let p=1;for(let i=2;i<=x;i++)p*=i;return p};return {value:target==="P"?fact(v.n)/fact(v.n-v.r):target==="r"?v.n-Math.log(v.P)/Math.log(v.n):v.r+Math.log(v.P)/Math.log(v.r+1),rearranged:"nPr = n!/(n−r)!"};}}));

// Sequences and series
maths.push(custom({id:"ap-nth",category:"Sequences",title:"Arithmetic nth term",description:"Nth term of an arithmetic progression",equation:"uₙ = a + (n−1)d",aliases:["arithmetic sequence","AP nth term","nth term AP"],inputs:[n("un","Nth term","uₙ"),n("a","First term","a"),n("n","Term number","n"),n("d","Common difference","d")],derive:(target,v)=>({value:target==="un"?v.a+(v.n-1)*v.d:target==="a"?v.un-(v.n-1)*v.d:target==="d"?(v.un-v.a)/(v.n-1):(v.un-v.a)/v.d+1,rearranged:"uₙ = a + (n−1)d"})}));
maths.push(custom({id:"ap-sum",category:"Sequences",title:"Arithmetic series sum",description:"Sum of the first n terms",equation:"Sₙ = n/2[2a + (n−1)d]",aliases:["arithmetic series","AP sum"],inputs:[n("S","Sum","Sₙ"),n("n","Number of terms","n"),n("a","First term","a"),n("d","Common difference","d")],derive:(target,v)=>({value:target==="S"?v.n/2*(2*v.a+(v.n-1)*v.d):target==="a"?v.S*2/v.n/2-(v.n-1)*v.d/2:target==="d"?(2*v.S/v.n-2*v.a)/(v.n-1):(Math.sqrt((2*v.a-v.d)**2+8*v.d*v.S)- (2*v.a-v.d))/(2*v.d),rearranged:"Sₙ = n/2[2a + (n−1)d]"})}));
maths.push(custom({id:"gp-nth",category:"Sequences",title:"Geometric nth term",description:"Nth term of a geometric progression",equation:"uₙ = arⁿ⁻¹",aliases:["geometric sequence","GP nth term"],inputs:[n("un","Nth term","uₙ"),n("a","First term","a"),n("n","Term number","n"),n("r","Common ratio","r")],derive:(target,v)=>({value:target==="un"?v.a*v.r**(v.n-1):target==="a"?v.un/v.r**(v.n-1):target==="r"?(v.un/v.a)**(1/(v.n-1)):(Math.log(v.un/v.a)/Math.log(v.r))+1,rearranged:"uₙ = arⁿ⁻¹"})}));
maths.push(custom({id:"gp-sum",category:"Sequences",title:"Geometric series sum",description:"Sum of a finite geometric progression",equation:"Sₙ = a(1−rⁿ)/(1−r)",aliases:["geometric series","GP sum"],inputs:[n("S","Sum","Sₙ"),n("a","First term","a"),n("r","Common ratio","r"),n("n","Number of terms","n")],derive:(target,v)=>({value:target==="S"?v.a*(1-v.r**v.n)/(1-v.r):target==="a"?v.S*(1-v.r)/(1-v.r**v.n):target==="r"?v.r:(Math.log(1-v.S*(1-v.r)/v.a)/Math.log(v.r)),rearranged:"Sₙ = a(1−rⁿ)/(1−r)"})}));
maths.push(custom({id:"gp-infinite",category:"Sequences",title:"Infinite geometric sum",description:"Sum to infinity for |r| < 1",equation:"S∞ = a/(1−r)",aliases:["sum to infinity","infinite geometric"],inputs:[n("S","Sum to infinity","S∞"),n("a","First term","a"),n("r","Common ratio","r")],derive:(target,v)=>({value:target==="S"?v.a/(1-v.r):target==="a"?v.S*(1-v.r):1-v.a/v.S,rearranged:"S∞ = a/(1−r), |r| < 1"})}));

// Coordinate geometry
maths.push(custom({id:"gradient",category:"Coordinate geometry",title:"Gradient",description:"Gradient between two points",equation:"m = (y₂−y₁)/(x₂−x₁)",aliases:["gradient","slope"],inputs:[n("m","Gradient","m"),n("x1","x₁","x₁"),n("y1","y₁","y₁"),n("x2","x₂","x₂"),n("y2","y₂","y₂")],derive:(target,v)=>({value:target==="m"?(v.y2-v.y1)/(v.x2-v.x1):target==="y2"?v.y1+v.m*(v.x2-v.x1):target==="y1"?v.y2-v.m*(v.x2-v.x1):target==="x2"?v.x1+(v.y2-v.y1)/v.m:v.x2-(v.y2-v.y1)/v.m,rearranged:"m = (y₂−y₁)/(x₂−x₁)"})}));
maths.push(custom({id:"distance-2d",category:"Coordinate geometry",title:"Distance between points",description:"Euclidean distance in 2D",equation:"d = √[(x₂−x₁)² + (y₂−y₁)²]",aliases:["distance points","coordinate distance"],inputs:[n("d","Distance","d"),n("x1","x₁","x₁"),n("y1","y₁","y₁"),n("x2","x₂","x₂"),n("y2","y₂","y₂")],derive:(target,v)=>({value:target==="d"?Math.hypot(v.x2-v.x1,v.y2-v.y1):v.x1+v.d,rearranged:"d = √[(x₂−x₁)² + (y₂−y₁)²]"})}));
maths.push(custom({id:"midpoint",category:"Coordinate geometry",title:"Midpoint",description:"Midpoint of two points",equation:"M = ((x₁+x₂)/2, (y₁+y₂)/2)",aliases:["midpoint","mid point"],inputs:[n("mx","Midpoint x","xₘ"),n("my","Midpoint y","yₘ"),n("x1","x₁","x₁"),n("y1","y₁","y₁"),n("x2","x₂","x₂"),n("y2","y₂","y₂")],derive:(target,v)=>({value:target==="mx"?(v.x1+v.x2)/2:(v.y1+v.y2)/2,rearranged:"M = ((x₁+x₂)/2, (y₁+y₂)/2)"})}));
maths.push(custom({id:"line-equation",category:"Coordinate geometry",title:"Equation of a line",description:"Find y = mx + c",equation:"y = mx + c",aliases:["straight line","line equation","y=mx+c"],inputs:[n("y","y","y"),n("m","Gradient","m"),n("x","x","x"),n("c","Intercept","c")],derive:(target,v)=>({value:target==="y"?v.m*v.x+v.c:target==="m"?(v.y-v.c)/v.x:target==="x"?(v.y-v.c)/v.m:v.y-v.m*v.x,rearranged:"y = mx + c"})}));
maths.push(custom({id:"circle-equation-radius",category:"Coordinate geometry",title:"Circle radius",description:"Radius from circle equation x²+y²+Dx+Ey+F=0",equation:"r² = (D/2)² + (E/2)² − F",aliases:["circle radius","circle equation"],inputs:[n("r2","Radius squared","r²"),n("D","x coefficient","D"),n("E","y coefficient","E"),n("F","Constant","F")],derive:(target,v)=>({value:target==="r2"?v.D*v.D/4+v.E*v.E/4-v.F:Math.sqrt(Math.max(0,v.r2)),rearranged:"r² = (D/2)² + (E/2)² − F"})}));

// Trigonometry
maths.push(custom({id:"sine-rule-side",category:"Trigonometry",title:"Sine rule",description:"Find a missing side or angle",equation:"a/sin A = b/sin B",aliases:["sine rule","sine law"],inputs:[n("a","Side a","a"),n("A","Angle A","A","°","angle"),n("b","Side b","b"),n("B","Angle B","B","°","angle")],derive:(target,v)=>({value:target==="a"?v.b*Math.sin(v.A*Math.PI/180)/Math.sin(v.B*Math.PI/180):target==="b"?v.a*Math.sin(v.B*Math.PI/180)/Math.sin(v.A*Math.PI/180):target==="A"?Math.asin(v.a*Math.sin(v.B*Math.PI/180)/v.b)*180/Math.PI:Math.asin(v.b*Math.sin(v.A*Math.PI/180)/v.a)*180/Math.PI,rearranged:"a/sin A = b/sin B"})}));
maths.push(custom({id:"cosine-rule-side",category:"Trigonometry",title:"Cosine rule",description:"Find a side from two sides and included angle",equation:"a² = b² + c² − 2bc cos A",aliases:["cosine rule","cosine law"],inputs:[n("a","Side a","a"),n("b","Side b","b"),n("c","Side c","c"),n("A","Included angle","A","°","angle")],derive:(target,v)=>({value:target==="a"?Math.sqrt(v.b*v.b+v.c*v.c-2*v.b*v.c*Math.cos(v.A*Math.PI/180)):target==="b"?Math.sqrt(v.a*v.a+v.c*v.c-2*v.a*v.c*Math.cos(v.A*Math.PI/180)):target==="c"?Math.sqrt(v.a*v.a+v.b*v.b-2*v.a*v.b*Math.cos(v.A*Math.PI/180)):Math.acos((v.b*v.b+v.c*v.c-v.a*v.a)/(2*v.b*v.c))*180/Math.PI,rearranged:"a² = b² + c² − 2bc cos A"})}));
maths.push(prod({id:"triangle-area-sin",category:"Trigonometry",title:"Triangle area from two sides",description:"Area using two sides and included angle",equation:"Area = ½ab sin C",aliases:["triangle area","area sine"],outputKey:"A",coefficient:0.5,inputs:[n("A","Area","A"),n("a","Side a","a"),n("b","Side b","b"),n("sinC","sin C","sin C")],factors:[{key:"a",power:1},{key:"b",power:1},{key:"sinC",power:1}]}));
maths.push(custom({id:"radian-arc",category:"Trigonometry",title:"Arc length",description:"Arc length from radius and angle in radians",equation:"s = rθ",aliases:["arc length","radians arc"],inputs:[n("s","Arc length","s"),n("r","Radius","r"),n("theta","Angle","θ","rad","angle")],derive:(target,v)=>({value:target==="s"?v.r*v.theta:target==="r"?v.s/v.theta:v.s/v.r,rearranged:"s = rθ"})}));
maths.push(custom({id:"sector-area",category:"Trigonometry",title:"Sector area",description:"Area of a sector with angle in radians",equation:"A = ½r²θ",aliases:["sector area"],inputs:[n("A","Area","A"),n("r","Radius","r"),n("theta","Angle","θ","rad","angle")],derive:(target,v)=>({value:target==="A"?0.5*v.r*v.r*v.theta:target==="r"?Math.sqrt(2*v.A/v.theta):2*v.A/(v.r*v.r),rearranged:"A = ½r²θ"})}));

// Exponentials / logs
maths.push(custom({id:"exponential-value",category:"Exponentials & logs",title:"Exponential function",description:"Evaluate y = Ae^(kx)",equation:"y = Aeᵏˣ",aliases:["exponential","growth decay"],inputs:[n("y","Value","y"),n("A","Initial value","A"),n("k","Rate constant","k"),n("x","x","x")],derive:(target,v)=>({value:target==="y"?v.A*Math.exp(v.k*v.x):target==="A"?v.y/Math.exp(v.k*v.x):target==="k"?Math.log(v.y/v.A)/v.x:Math.log(v.y/v.A)/v.k,rearranged:"y = Aeᵏˣ"})}));
maths.push(custom({id:"log-change-base",category:"Exponentials & logs",title:"Change of base",description:"Convert a logarithm to a chosen base",equation:"logₐx = ln x / ln a",aliases:["log change base","logarithms"],inputs:[n("y","Logarithm","y"),n("x","Argument","x"),n("a","Base","a")],derive:(target,v)=>({value:target==="y"?Math.log(v.x)/Math.log(v.a):target==="x"?Math.exp(v.y*Math.log(v.a)):Math.exp(Math.log(v.x)/v.y),rearranged:"logₐx = ln x/ln a"})}));
maths.push(custom({id:"compound-growth",category:"Exponentials & logs",title:"Compound growth",description:"Value after repeated percentage growth",equation:"A = P(1+r)ⁿ",aliases:["compound interest","growth"],inputs:[n("A","Final amount","A"),n("P","Initial amount","P"),n("r","Rate","r","","percentage"),n("n","Number of periods","n")],derive:(target,v)=>({value:target==="A"?v.P*(1+v.r)**v.n:target==="P"?v.A/(1+v.r)**v.n:target==="r"?(v.A/v.P)**(1/v.n)-1:Math.log(v.A/v.P)/Math.log(1+v.r),rearranged:"A = P(1+r)ⁿ"})}));

// Differentiation
maths.push(custom({id:"power-diff",category:"Differentiation",title:"Power rule",description:"Differentiate a power",equation:"d(xⁿ)/dx = nxⁿ⁻¹",aliases:["differentiate power","power rule"],inputs:[n("y","Derivative","dy/dx"),n("a","Coefficient","a"),n("n","Power","n"),n("x","x","x")],derive:(target,v)=>({value:target==="y"?v.a*v.n*v.x**(v.n-1):v.a*v.x**v.n/(v.n*v.x**(v.n-1)),rearranged:"d(xⁿ)/dx = nxⁿ⁻¹"})}));
maths.push(custom({id:"product-rule-example",category:"Differentiation",title:"Product rule example",description:"Differentiate y = xⁿ(a+bx)",equation:"dy/dx = n xⁿ⁻¹(a+bx) + bxⁿ",aliases:["product rule","differentiate product"],inputs:[n("dy","Derivative","dy/dx"),n("n","Power","n"),n("a","Constant","a"),n("b","Coefficient","b"),n("x","x","x")],derive:(target,v)=>({value:v.n*v.x**(v.n-1)*(v.a+v.b*v.x)+v.b*v.x**v.n,rearranged:"dy/dx = n xⁿ⁻¹(a+bx) + bxⁿ"})}));
maths.push(custom({id:"exp-diff",category:"Differentiation",title:"Differentiate eˣ",description:"Derivative of an exponential",equation:"d(eᵏˣ)/dx = keᵏˣ",aliases:["differentiate exponential","e^x derivative"],inputs:[n("y","Derivative","dy/dx"),n("k","Rate","k"),n("x","x","x")],derive:(target,v)=>({value:v.k*Math.exp(v.k*v.x),rearranged:"d(eᵏˣ)/dx = keᵏˣ"})}));
maths.push(custom({id:"ln-diff",category:"Differentiation",title:"Differentiate ln x",description:"Derivative of a natural logarithm",equation:"d(ln x)/dx = 1/x",aliases:["ln derivative","differentiate ln"],inputs:[n("y","Derivative","dy/dx"),n("x","x","x")],derive:(target,v)=>({value:1/v.x,rearranged:"d(ln x)/dx = 1/x"})}));
maths.push(custom({id:"trig-diff",category:"Differentiation",title:"Differentiate sin/cos",description:"Basic trigonometric derivatives",equation:"d(sin x)/dx = cos x",aliases:["trig differentiation","sin derivative"],inputs:[n("y","Derivative","dy/dx"),n("x","x","x"),n("kind","Function 1=sin 2=cos","k")],derive:(target,v)=>({value:v.kind===1?Math.cos(v.x):-Math.sin(v.x),rearranged:"sin x → cos x; cos x → −sin x"})}));
maths.push(custom({id:"stationary-point-x",category:"Differentiation",title:"Stationary point x",description:"Solve a simple quadratic derivative for a stationary point",equation:"dy/dx = ax² + bx + c = 0",aliases:["stationary point","turning point","gradient zero"],inputs:[n("x1","Stationary x₁","x₁"),n("x2","Stationary x₂","x₂"),n("a","Coefficient a","a"),n("b","Coefficient b","b"),n("c","Coefficient c","c")],derive:(target,v)=>{const d=v.b*v.b-4*v.a*v.c;return {value:target==="x1"?(-v.b+Math.sqrt(d))/(2*v.a):(-v.b-Math.sqrt(d))/(2*v.a),rearranged:"set dy/dx = 0 and solve"};}}));

// Integration / numerical methods
maths.push(custom({id:"power-integral",category:"Integration",title:"Power integral",description:"Indefinite integral of a power",equation:"∫xⁿdx = xⁿ⁺¹/(n+1) + C",aliases:["integrate power","power integration"],inputs:[n("y","Integral","∫xⁿ dx"),n("n","Power","n"),n("x","x","x")],derive:(target,v)=>({value:v.x**(v.n+1)/(v.n+1),rearranged:"∫xⁿdx = xⁿ⁺¹/(n+1) + C"})}));
maths.push(custom({id:"exp-integral",category:"Integration",title:"Exponential integral",description:"Integral of eᵏˣ",equation:"∫eᵏˣdx = eᵏˣ/k + C",aliases:["integrate exponential"],inputs:[n("y","Integral","∫eᵏˣdx"),n("k","Rate","k"),n("x","x","x")],derive:(target,v)=>({value:Math.exp(v.k*v.x)/v.k,rearranged:"∫eᵏˣdx = eᵏˣ/k + C"})}));
maths.push(custom({id:"definite-integral-power",category:"Integration",title:"Definite integral",description:"Evaluate an integral of xⁿ from a to b",equation:"∫ₐᵇ xⁿ dx = [xⁿ⁺¹/(n+1)]ₐᵇ",aliases:["definite integral","area under curve"],inputs:[n("I","Integral","I"),n("n","Power","n"),n("a","Lower limit","a"),n("b","Upper limit","b")],derive:(target,v)=>({value:(v.b**(v.n+1)-v.a**(v.n+1))/(v.n+1),rearranged:"I = (bⁿ⁺¹ − aⁿ⁺¹)/(n+1)"})}));
maths.push(custom({id:"trapezium-rule",category:"Numerical methods",title:"Trapezium rule",description:"Approximate area under a curve",equation:"∫ᵃᵇf(x)dx ≈ h/2[y₀ + yₙ + 2Σyᵢ]",aliases:["trapezium rule","numerical integration"],inputs:[n("I","Approximate integral","I"),n("h","Step width","h"),n("y0","First y","y₀"),n("yn","Last y","yₙ"),n("sum","Sum of interior y values","Σyᵢ")],derive:(target,v)=>({value:v.h/2*(v.y0+v.yn+2*v.sum),rearranged:"I ≈ h/2[y₀+yₙ+2Σyᵢ]"})}));
maths.push(custom({id:"newton-raphson",category:"Numerical methods",title:"Newton–Raphson",description:"Next approximation to a root",equation:"xₙ₊₁ = xₙ − f(xₙ)/f′(xₙ)",aliases:["Newton Raphson","root finding"],inputs:[n("next","Next value","xₙ₊₁"),n("x","Current value","xₙ"),n("f","f(xₙ)","f(xₙ)"),n("df","f′(xₙ)","f′(xₙ)")],derive:(target,v)=>({value:v.x-v.f/v.df,rearranged:"xₙ₊₁ = xₙ − f(xₙ)/f′(xₙ)"})}));
maths.push(custom({id:"volume-of-revolution",category:"Integration",title:"Volume of revolution",description:"Volume formed by rotating y about the x-axis",equation:"V = π∫y²dx",aliases:["volume of revolution"],inputs:[n("V","Volume","V"),n("I","Integral of y²","∫y²dx"),n("pi","π factor","π")],derive:(target,v)=>({value:Math.PI*v.I,rearranged:"V = π∫y²dx"})}));

// Vectors
maths.push(custom({id:"vector-magnitude",category:"Vectors",title:"Vector magnitude",description:"Magnitude of a 2D vector",equation:"|a| = √(x²+y²)",aliases:["vector magnitude","modulus vector"],inputs:[n("mag","Magnitude","|a|"),n("x","x component","x"),n("y","y component","y")],derive:(target,v)=>({value:target==="mag"?Math.hypot(v.x,v.y):Math.sqrt(Math.max(0,v.mag*v.mag-v.y*v.y)),rearranged:"|a| = √(x²+y²)"})}));
maths.push(custom({id:"dot-product",category:"Vectors",title:"Dot product",description:"Scalar product of two 2D vectors",equation:"a·b = x₁x₂ + y₁y₂",aliases:["dot product","scalar product"],inputs:[n("dot","Dot product","a·b"),n("x1","x₁","x₁"),n("y1","y₁","y₁"),n("x2","x₂","x₂"),n("y2","y₂","y₂")],derive:(target,v)=>({value:v.x1*v.x2+v.y1*v.y2,rearranged:"a·b = x₁x₂ + y₁y₂"})}));
